import json
for p,label in [('2026-10-19T12-33-12-416Z_01a15426-d0df-7234-a311-e5f9f6f4c036.jsonl','acc-a'),
                ('2026-10-19T12-33-16-146Z_01a15426-df72-7379-b53a-dbb6f851f163.jsonl','acc-b')]:
    print('#####',label,p)
    for l in open(p):
        if not l.strip(): continue
        r=json.loads(l)
        t=r.get('type')
        if t=='message':
            m=r.get('message',{})
            role=m.get('role')
            for c in m.get('content',[]) if isinstance(m.get('content'),list) else []:
                if c.get('type')=='toolCall':
                    name=c.get('name'); args=c.get('arguments') or {}
                    s=json.dumps(args,ensure_ascii=False)
                    print(f"  [{r.get('timestamp')}] {name}: {s[:200]}")
            if role=='user':
                c=m.get('content')
                txt=c if isinstance(c,str) else json.dumps(c,ensure_ascii=False)
                print(f"  [{r.get('timestamp')}] USER: {txt[:160]}")
    print()
EOF

